import java.math.BigInteger;

public final class Solution {
    private Solution() {}

    public enum ServiceLevel {
        UNSATISFACTORY(500), OKAY(1000), SOLID(1500), IMPRESSIVE(2000), OUTSTANDING(2500);

        private final int basisPoints;

        ServiceLevel(int basisPoints) {
            this.basisPoints = basisPoints;
        }
    }

    public static final class PaymentSummary {
        private final long discountCents;
        private final long taxCents;
        private final long gratuityCents;
        private final long totalCents;
        private final int participantCount;

        private PaymentSummary(long discountCents, long taxCents, long gratuityCents,
                               long totalCents, int participantCount) {
            this.discountCents = discountCents;
            this.taxCents = taxCents;
            this.gratuityCents = gratuityCents;
            this.totalCents = totalCents;
            this.participantCount = participantCount;
        }

        public long getDiscountCents() {
            return discountCents;
        }

        public long getTaxCents() {
            return taxCents;
        }

        public long getGratuityCents() {
            return gratuityCents;
        }

        public long getTotalCents() {
            return totalCents;
        }

        public int getParticipantCount() {
            return participantCount;
        }

        public long getShareCents(int participantIndex) {
            if (participantIndex < 0 || participantIndex >= participantCount) {
                throw new IndexOutOfBoundsException("Invalid participant index: " + participantIndex);
            }
            long base = totalCents / participantCount;
            long remainder = totalCents % participantCount;
            return base + (participantIndex < remainder ? 1L : 0L);
        }
    }

    public static PaymentSummary calculatePayment(long subtotalCents, int taxBasisPoints,
                                                   int discountBasisPoints, ServiceLevel serviceLevel,
                                                   int participantCount) {
        if (subtotalCents < 0
                || taxBasisPoints < 0 || taxBasisPoints > 10000
                || discountBasisPoints < 0 || discountBasisPoints > 10000
                || serviceLevel == null || participantCount < 1) {
            throw new IllegalArgumentException("Invalid payment input");
        }

        long discount = percentage(subtotalCents, discountBasisPoints);
        long discountedSubtotal = Math.subtractExact(subtotalCents, discount);
        long tax = percentage(discountedSubtotal, taxBasisPoints);
        long gratuity = percentage(discountedSubtotal, serviceLevel.basisPoints);
        long total = Math.addExact(Math.addExact(discountedSubtotal, tax), gratuity);
        return new PaymentSummary(discount, tax, gratuity, total, participantCount);
    }

    private static long percentage(long cents, int basisPoints) {
        return BigInteger.valueOf(cents)
                .multiply(BigInteger.valueOf(basisPoints))
                .add(BigInteger.valueOf(5000L))
                .divide(BigInteger.valueOf(10000L))
                .longValueExact();
    }
}

import java.io.StringReader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;
import org.xml.sax.InputSource;

public final class Solution {
    private Solution() {}

    public static final class Notice {
        private final int number;
        private final String category;
        private final List<String> messages;

        private Notice(int number, String category, List<String> messages) {
            this.number = number;
            this.category = category;
            this.messages = Collections.unmodifiableList(new ArrayList<>(messages));
        }

        public int getNumber() {
            return number;
        }

        public String getCategory() {
            return category;
        }

        public List<String> getMessages() {
            return messages;
        }
    }

    public static Notice parseNotice(String xml) {
        if (xml == null || xml.trim().isEmpty()) {
            throw new IllegalArgumentException("XML must be nonblank");
        }

        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");
            factory.setExpandEntityReferences(false);
            factory.setXIncludeAware(false);

            Document document = factory.newDocumentBuilder()
                    .parse(new InputSource(new StringReader(xml)));
            Element root = document.getDocumentElement();
            if (root == null || !"Notice".equals(root.getTagName())) {
                throw new IllegalArgumentException("Root must be Notice");
            }

            Element numberElement = null;
            Element categoryElement = null;
            Element messagesElement = null;
            NodeList rootChildren = root.getChildNodes();
            for (int i = 0; i < rootChildren.getLength(); i++) {
                Node node = rootChildren.item(i);
                if (node.getNodeType() != Node.ELEMENT_NODE) {
                    continue;
                }
                Element element = (Element) node;
                String name = element.getTagName();
                if ("Number".equals(name) && numberElement == null) {
                    numberElement = element;
                } else if ("Category".equals(name) && categoryElement == null) {
                    categoryElement = element;
                } else if ("Messages".equals(name) && messagesElement == null) {
                    messagesElement = element;
                } else {
                    throw new IllegalArgumentException("Unexpected or duplicate element: " + name);
                }
            }

            if (numberElement == null || categoryElement == null || messagesElement == null) {
                throw new IllegalArgumentException("Required element missing");
            }

            String numberText = leafText(numberElement, "Number");
            final int number;
            try {
                number = Integer.parseInt(numberText);
            } catch (NumberFormatException ex) {
                throw new IllegalArgumentException("Number must be a valid decimal integer", ex);
            }
            if (number < 0) {
                throw new IllegalArgumentException("Number must be nonnegative");
            }

            String category = leafText(categoryElement, "Category");
            List<String> messages = new ArrayList<>();
            NodeList messageNodes = messagesElement.getChildNodes();
            for (int i = 0; i < messageNodes.getLength(); i++) {
                Node node = messageNodes.item(i);
                if (node.getNodeType() != Node.ELEMENT_NODE) {
                    continue;
                }
                Element element = (Element) node;
                if (!"Message".equals(element.getTagName())) {
                    throw new IllegalArgumentException(
                            "Unexpected Messages child: " + element.getTagName());
                }
                messages.add(leafText(element, "Message"));
            }
            if (messages.isEmpty()) {
                throw new IllegalArgumentException("At least one message is required");
            }

            return new Notice(number, category, messages);
        } catch (IllegalArgumentException ex) {
            throw ex;
        } catch (Exception ex) {
            throw new IllegalArgumentException("Invalid XML: " + String.valueOf(ex.getMessage()), ex);
        }
    }

    private static String leafText(Element element, String name) {
        NodeList children = element.getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
            if (children.item(i).getNodeType() == Node.ELEMENT_NODE) {
                throw new IllegalArgumentException(name + " must not contain elements");
            }
        }

        String value = element.getTextContent().trim();
        if (value.isBlank()) {
            throw new IllegalArgumentException(name + " must be nonblank");
        }
        return value;
    }
}

