package solution

import (
	"errors"
	"sort"
	"strings"
)

type Reservation struct {
	ID    int
	Guest string
	Seats int
}

type Book struct {
	capacity int
	used     int
	nextID   int
	entries  map[int]Reservation
}

var ErrInvalidCapacity = errors.New("invalid capacity")
var ErrInvalidReservation = errors.New("invalid reservation")
var ErrCapacityExceeded = errors.New("capacity exceeded")
var ErrReservationNotFound = errors.New("reservation not found")
var ErrInvalidLimit = errors.New("invalid limit")

func NewBook(capacity int) (*Book, error) {
	if capacity < 1 {
		return nil, ErrInvalidCapacity
	}
	return &Book{capacity: capacity, nextID: 1, entries: make(map[int]Reservation)}, nil
}

func (b *Book) Add(guest string, seats int) (int, error) {
	if strings.TrimSpace(guest) == "" || seats < 1 {
		return 0, ErrInvalidReservation
	}
	if seats > b.capacity-b.used {
		return 0, ErrCapacityExceeded
	}
	id := b.nextID
	b.nextID++
	b.used += seats
	b.entries[id] = Reservation{ID: id, Guest: guest, Seats: seats}
	return id, nil
}

func (b *Book) Get(id int) (Reservation, error) {
	reservation, ok := b.entries[id]
	if !ok {
		return Reservation{}, ErrReservationNotFound
	}
	return reservation, nil
}

func (b *Book) List(limit int) ([]Reservation, error) {
	if limit < 0 {
		return nil, ErrInvalidLimit
	}
	result := make([]Reservation, 0)
	if limit == 0 {
		return result, nil
	}
	ids := make([]int, 0, len(b.entries))
	for id := range b.entries {
		ids = append(ids, id)
	}
	sort.Ints(ids)
	for _, id := range ids {
		if len(result) == limit {
			break
		}
		result = append(result, b.entries[id])
	}
	return result, nil
}

func (b *Book) Cancel(id int) error {
	reservation, ok := b.entries[id]
	if !ok {
		return ErrReservationNotFound
	}
	delete(b.entries, id)
	b.used -= reservation.Seats
	return nil
}

package solution

import (
	"errors"
	"sync"
)

var (
	ErrInvalidConfig = errors.New("invalid mailbox config")
	ErrInvalidPacket = errors.New("invalid packet")
	ErrMailboxFull   = errors.New("mailbox full")
)

type MailboxConfig struct {
	Capacity        int
	MaxPayloadBytes int
}

type Packet struct {
	Topic   string
	Payload []byte
}

type Mailbox struct {
	mu      sync.Mutex
	config  MailboxConfig
	packets []Packet
}

func NewMailbox(config MailboxConfig) (*Mailbox, error) {
	if config.Capacity <= 0 || config.MaxPayloadBytes <= 0 {
		return nil, ErrInvalidConfig
	}
	return &Mailbox{config: config}, nil
}

func copyPayload(payload []byte) []byte {
	copied := make([]byte, len(payload))
	copy(copied, payload)
	return copied
}

func (m *Mailbox) Enqueue(packet Packet) error {
	if packet.Topic == "" || len(packet.Payload) > m.config.MaxPayloadBytes {
		return ErrInvalidPacket
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	if len(m.packets) == m.config.Capacity {
		return ErrMailboxFull
	}
	m.packets = append(m.packets, Packet{
		Topic:   packet.Topic,
		Payload: copyPayload(packet.Payload),
	})
	return nil
}

func (m *Mailbox) Drain(topic string, limit int) ([]Packet, error) {
	if topic == "" || limit < 0 {
		return nil, ErrInvalidPacket
	}
	result := make([]Packet, 0)
	if limit == 0 {
		return result, nil
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	kept := make([]Packet, 0, len(m.packets))
	for _, packet := range m.packets {
		if packet.Topic == topic && len(result) < limit {
			result = append(result, Packet{
				Topic:   packet.Topic,
				Payload: copyPayload(packet.Payload),
			})
		} else {
			kept = append(kept, packet)
		}
	}
	m.packets = kept
	return result, nil
}

func (m *Mailbox) Count(topic string) int {
	m.mu.Lock()
	defer m.mu.Unlock()
	if topic == "" {
		return len(m.packets)
	}
	count := 0
	for _, packet := range m.packets {
		if packet.Topic == topic {
			count++
		}
	}
	return count
}

'use strict';

const FIELDS = ['key', 'code', 'owner', 'openedOn'];

function copyValidEntry(entry) {
  if (entry === null || typeof entry !== 'object' ||
      FIELDS.some((field) => typeof entry[field] !== 'string')) {
    throw new TypeError('invalid entry');
  }
  return {
    ...entry,
    key: entry.key,
    code: entry.code,
    owner: entry.owner,
    openedOn: entry.openedOn
  };
}

function createRegistry(entries = []) {
  if (!Array.isArray(entries)) throw new TypeError('entries must be an array');
  const copies = entries.map(copyValidEntry);
  const keys = new Set();
  for (const entry of copies) {
    if (keys.has(entry.key)) throw new Error('duplicate key');
    keys.add(entry.key);
  }
  return { entries: copies };
}

function validateRegistry(registry) {
  if (registry === null || typeof registry !== 'object' || !Array.isArray(registry.entries)) {
    throw new TypeError('invalid registry');
  }
}

function executeCommand(registry, command) {
  validateRegistry(registry);
  if (command === null || typeof command !== 'object') throw new TypeError('invalid command');

  if (command.type === 'add') {
    const entry = copyValidEntry(command.entry);
    if (registry.entries.some((item) => item.key === entry.key)) throw new Error('duplicate key');
    return { entries: [...registry.entries, entry] };
  }

  if (command.type === 'remove') {
    if (typeof command.key !== 'string') throw new TypeError('invalid key');
    const index = registry.entries.findIndex((item) => item.key === command.key);
    if (index < 0) return registry;
    return { entries: registry.entries.filter((_, i) => i !== index) };
  }

  if (command.type === 'edit') {
    if (typeof command.key !== 'string') throw new TypeError('invalid key');
    const index = registry.entries.findIndex((item) => item.key === command.key);
    if (index < 0) return registry;
    if (command.changes === null || typeof command.changes !== 'object') {
      throw new TypeError('invalid edit');
    }

    const current = registry.entries[index];
    const replacement = {
      ...current,
      key: current.key,
      code: current.code,
      owner: current.owner,
      openedOn: current.openedOn
    };
    for (const field of ['code', 'owner', 'openedOn']) {
      if (Object.prototype.hasOwnProperty.call(command.changes, field)) {
        if (typeof command.changes[field] !== 'string') throw new TypeError('invalid change');
        replacement[field] = command.changes[field];
      }
    }
    const entries = registry.entries.slice();
    entries[index] = replacement;
    return { entries };
  }

  throw new TypeError('unknown command');
}

function searchEntries(registry, term) {
  validateRegistry(registry);
  if (typeof term !== 'string') throw new TypeError('term must be a string');
  const needle = term.toLowerCase();
  return registry.entries.filter((entry) =>
    entry.code.toLowerCase().includes(needle) || entry.owner.toLowerCase().includes(needle)
  );
}

module.exports = { createRegistry, executeCommand, searchEntries };

function emptyState() {
  return { byId: Object.create(null), order: [] };
}

function partReducer(state, action) {
  const current = state === undefined ? emptyState() : state;
  if (action === null || typeof action !== 'object') return current;

  if (action.type === 'REPLACE_PARTS') {
    if (!Array.isArray(action.parts)) throw new TypeError('parts must be an array');

    const byId = Object.create(null);
    const order = [];
    const seen = new Set();
    for (const part of action.parts) {
      if (part === null || typeof part !== 'object' ||
          typeof part.id !== 'string' || part.id.length === 0 || seen.has(part.id) ||
          typeof part.label !== 'string' || typeof part.hours !== 'number' ||
          !Number.isFinite(part.hours) || part.hours < 0) {
        throw new TypeError('Invalid or duplicate part');
      }
      seen.add(part.id);
      order.push(part.id);
      byId[part.id] = { id: part.id, label: part.label, hours: part.hours, pinned: false };
    }
    return { byId, order };
  }

  if (action.type === 'PIN_PART' || action.type === 'UNPIN_PART') {
    if (typeof action.id !== 'string' || action.id.length === 0) {
      throw new TypeError('Invalid part id');
    }
    if (!Object.prototype.hasOwnProperty.call(current.byId, action.id)) return current;

    const byId = Object.create(null);
    for (const key of Reflect.ownKeys(current.byId)) {
      byId[key] = current.byId[key];
    }

    const part = current.byId[action.id];
    byId[action.id] = {
      ...part,
      id: part.id,
      label: part.label,
      hours: part.hours,
      pinned: action.type === 'PIN_PART'
    };
    return { byId, order: current.order };
  }

  return current;
}

module.exports = partReducer;

export interface Performance {
  readonly id: string;
  readonly venueId: string;
}

export interface ReservationDraft {
  readonly id?: string;
  readonly customerId: string;
  readonly performanceId: string;
  readonly seat: string;
}

export interface Reservation {
  readonly id: string;
  readonly customerId: string;
  readonly performanceId: string;
  readonly seat: string;
}

type ReservationPatch = Partial<Omit<ReservationDraft, "id">>;

function nonempty(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

export class ReservationStore {
  private readonly performances = new Map<string, Performance>();
  private readonly reservations = new Map<string, Reservation>();
  private nextId = 1;

  constructor(performances: readonly Performance[]) {
    for (const item of performances) {
      if (!item || !nonempty(item.id) || !nonempty(item.venueId) || this.performances.has(item.id)) {
        throw new TypeError("Invalid or duplicate performance");
      }
      this.performances.set(item.id, { id: item.id, venueId: item.venueId });
    }
  }

  add(draft: ReservationDraft): Reservation {
    this.validate(draft);
    let id = draft.id;
    if (id !== undefined && this.reservations.has(id)) {
      throw new RangeError("Duplicate reservation ID");
    }
    if (id === undefined) {
      do {
        id = `reservation-${this.nextId++}`;
      } while (this.reservations.has(id));
    }
    const value: Reservation = {
      id,
      customerId: draft.customerId,
      performanceId: draft.performanceId,
      seat: draft.seat
    };
    this.reservations.set(id, value);
    return { ...value };
  }

  get(id: string): Reservation | null {
    const value = this.reservations.get(id);
    return value ? { ...value } : null;
  }

  byCustomer(customerId: string): Reservation[] {
    return [...this.reservations.values()]
      .filter((value) => value.customerId === customerId)
      .map((value) => ({ ...value }));
  }

  byPerformance(performanceId: string): Reservation[] {
    return [...this.reservations.values()]
      .filter((value) => value.performanceId === performanceId)
      .map((value) => ({ ...value }));
  }

  update(id: string, patch: ReservationPatch): Reservation | null {
    const current = this.reservations.get(id);
    if (!current) return null;

    const candidate: Reservation = {
      id: current.id,
      customerId: patch.customerId === undefined ? current.customerId : patch.customerId,
      performanceId: patch.performanceId === undefined ? current.performanceId : patch.performanceId,
      seat: patch.seat === undefined ? current.seat : patch.seat
    };
    this.validate(candidate);
    this.reservations.set(id, candidate);
    return { ...candidate };
  }

  delete(id: string): boolean {
    return this.reservations.delete(id);
  }

  private validate(value: ReservationDraft): void {
    if (!value || !nonempty(value.customerId) || !nonempty(value.performanceId) || !nonempty(value.seat) ||
        (value.id !== undefined && !nonempty(value.id))) {
      throw new TypeError("Invalid reservation");
    }
    if (!this.performances.has(value.performanceId)) {
      throw new RangeError("Unknown performance");
    }
  }
}
